package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for BigFraction.floatValue()
 */
public class BigFraction_floatValue_TriageGen0Test {

    private static final float EPSILON = 1e-6f;

    @Test
    public void testFloatValue_SimpleFraction() {
        // 1/2 = 0.5f
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_IntegerNumerator() {
        // 5/1 = 5.0f
        BigFraction fraction = new BigFraction(5);
        assertEquals(5.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeFraction() {
        // -3/4 = -0.75f
        BigFraction fraction = new BigFraction(-3, 4);
        assertEquals(-0.75f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_LargeValues() {
        // Test values that exceed standard int range but fit in float precision
        // 1000000 / 1 = 1000000.0f
        BigFraction fraction = new BigFraction(new BigInteger("1000000"), BigInteger.ONE);
        assertEquals(1000000.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_ZeroNumerator() {
        // 0/5 = 0.0f
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_VerySmallFraction() {
        // 1 / 1000000 = 0.000001f
        BigFraction fraction = new BigFraction(1, 1000000);
        assertEquals(0.000001f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_PrecisionLoss() {
        // BigFraction can hold much higher precision than float.
        // Using a value that will be truncated by float conversion.
        // 1/3 is 0.3333333333...
        BigFraction fraction = new BigFraction(1, 3);
        float expected = (float) (1.0 / 3.0);
        assertEquals(expected, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_LargeDenominator() {
        // Test division by a large denominator
        BigFraction fraction = new BigFraction(1, new BigInteger("1000000000"));
        assertEquals(0.0f, fraction.floatValue(), EPSILON); // Should be near zero/underflow for float
    }

    @Test
    public void testFloatValue_ExtremeLargeValues() {
        // Test values that result in Float.POSITIVE_INFINITY
        // BigInteger can be much larger than Float.MAX_VALUE
        BigInteger huge = new BigInteger("1" + "0".repeat(40)); 
        BigFraction fraction = new BigFraction(huge, BigInteger.ONE);
        assertEquals(Float.POSITIVE_INFINITY, fraction.floatValue(), 0.0f);
    }

    @Test
    public void testFloatValue_ExtremeNegativeValues() {
        // Test values that result in Float.NEGATIVE_INFINITY
        BigInteger huge = new BigInteger("1" + "0".repeat(40));
        BigFraction fraction = new BigFraction(huge.negate(), BigInteger.ONE);
        assertEquals(Float.NEGATIVE_INFINITY, fraction.floatValue(), 0.0f);
    }
}
